{"files":[{"path":"tests/conftest.py","content":""""Shared fixtures for the URL shortener suite.

Every test gets a freshly constructed application (so the in-process rate
limiter starts with empty buckets) backed by its own SQLite file underneath
``tmp_path``, plus a stubbed name resolver so that no test ever performs DNS or
network I/O.  Nothing is shared between tests and nothing sleeps.
"""
from __future__ import annotations

import ipaddress
import itertools
import os
import socket
import sqlite3
import sys
import tempfile
import time as real_time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional

import pytest
from fastapi.testclient import TestClient

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

# app.main builds an application at import time and that construction touches
# LINKS_DB_PATH; point it at a throwaway directory before importing.
_IMPORT_DIR = tempfile.mkdtemp(prefix="links-import-")
os.environ["LINKS_DB_PATH"] = os.path.join(_IMPORT_DIR, "import.db")

import app.codes as codes_module  # noqa: E402
import app.main as main_module  # noqa: E402
import app.ratelimit as ratelimit_module  # noqa: E402
from app.main import create_app  # noqa: E402

TS_FORMAT = "%Y-%m-%dT%H:%M:%S.%fZ"
DEFAULT_HOST = "203.0.113.10"
OTHER_HOST = "198.51.100.23"
PUBLIC_IPV4 = "93.184.216.34"
PUBLIC_IPV6 = "2606:2800:220:1:248:1893:25c8:1946"

LINK_COLUMNS = ["id", "code", "url", "created_at", "expires_at"]
CLICK_COLUMNS = ["id", "link_id", "clicked_at", "referrer", "user_agent"]


# ---------------------------------------------------------------------------
# environment hygiene
# ---------------------------------------------------------------------------
@pytest.fixture(autouse=True)
def _clean_env(monkeypatch):
    """Remove every service variable so ambient configuration cannot leak in."""
    for name in list(os.environ):
        if name.startswith("LINKS_") or name == "SHORTENER_API_KEYS":
            monkeypatch.delenv(name, raising=False)


@pytest.fixture(autouse=True)
def _no_outbound_connections(monkeypatch):
    def refuse(*args, **kwargs):  # pragma: no cover - only fires on a bug
        raise AssertionError("the service must never open an outbound connection")

    monkeypatch.setattr(socket, "create_connection", refuse, raising=False)


# ---------------------------------------------------------------------------
# deterministic resolver
# ---------------------------------------------------------------------------
class FakeResolver:
    """Stand-in for :func:`socket.getaddrinfo` with no network access."""

    def __init__(self) -> None:
        self.map: Dict[str, List[str]] = {}
        self.failures = set()
        self.lookups: List[str] = []

    def set(self, host: str, addresses: Iterable[str]) -> None:
        self.map[host.strip("[]").lower()] = list(addresses)

    def fail(self, host: str) -> None:
        self.failures.add(host.strip("[]").lower())

    def _addresses_for(self, host: str) -> List[str]:
        name = (host or "").strip("[]").lower()
        self.lookups.append(name)
        if name in self.failures:
            raise socket.gaierror(-2, "Name or service not known")
        if name in self.map:
            return list(self.map[name])
        try:
            ipaddress.ip_address(name)
            return [name]
        except ValueError:
            return [PUBLIC_IPV4]

    def getaddrinfo(self, host, port=0, family=0, type=0, proto=0, flags=0):
        try:
            portnum = int(port)
        except (TypeError, ValueError):
            portnum = 0
        out = []
        for address in self._addresses_for(host):
            parsed = ipaddress.ip_address(address)
            if parsed.version == 4:
                out.append((socket.AF_INET, socket.SOCK_STREAM, 6, "", (address, portnum)))
            else:
                out.append(
                    (socket.AF_INET6, socket.SOCK_STREAM, 6, "", (address, portnum, 0, 0))
                )
        return out

    def gethostbyname(self, host):
        for address in self._addresses_for(host):
            if ipaddress.ip_address(address).version == 4:
                return address
        raise socket.gaierror(-2, "Name or service not known")


@pytest.fixture(autouse=True)
def fake_dns(monkeypatch):
    resolver = FakeResolver()
    monkeypatch.setattr(socket, "getaddrinfo", resolver.getaddrinfo)
    monkeypatch.setattr(socket, "gethostbyname", resolver.gethostbyname)
    return resolver


# ---------------------------------------------------------------------------
# limiter clock (advance the window without sleeping)
# ---------------------------------------------------------------------------
class FakeClock:
    """Frozen, advanceable replacement for the limiter's time source."""

    def __init__(self, real) -> None:
        self._real = real
        self.value = 100000.0

    def monotonic(self) -> float:
        return self.value

    def time(self) -> float:
        return self.value

    def advance(self, seconds: float) -> None:
        self.value += float(seconds)

    def __getattr__(self, name):  # pragma: no cover - delegation only
        return getattr(self._real, name)


@pytest.fixture
def limiter_clock(monkeypatch):
    clock = FakeClock(real_time)
    monkeypatch.setattr(ratelimit_module, "time", clock, raising=False)
    return clock


# ---------------------------------------------------------------------------
# scripted short codes (collision forcing)
# ---------------------------------------------------------------------------
_FALLBACK_COUNTER = itertools.count(1)


def _fallback_code(length: int = 7) -> str:
    text = "Zz{0:05d}".format(next(_FALLBACK_COUNTER))
    if len(text) >= length:
        return text[:length]
    return text + "0" * (length - len(text))


class ScriptedCodes:
    """Deterministic short code generator used to force UNIQUE collisions."""

    def __init__(self, codes: Iterable[str]) -> None:
        self.queue = list(codes)
        self.calls = 0
        self.produced: List[str] = []

    def __call__(self, length: int = 7, *args, **kwargs) -> str:
        self.calls += 1
        if self.queue:
            value = self.queue.pop(0)
        else:
            value = _fallback_code(int(length or 7))
        self.produced.append(value)
        return value


@pytest.fixture
def scripted_codes(monkeypatch):
    def install(codes: Iterable[str]) -> ScriptedCodes:
        stub = ScriptedCodes(codes)
        monkeypatch.setattr(main_module, "generate_code", stub, raising=False)
        monkeypatch.setattr(codes_module, "generate_code", stub, raising=False)
        return stub

    return install


# ---------------------------------------------------------------------------
# the application under test
# ---------------------------------------------------------------------------
class Harness:
    """HTTP + database view of one freshly built application."""

    def __init__(self, application, db_path) -> None:
        self.app = application
        self.db_path = str(db_path)
        self._clients: Dict[str, TestClient] = {}

    # -- HTTP -------------------------------------------------------------
    def client(self, host: str = DEFAULT_HOST) -> TestClient:
        if host not in self._clients:
            try:
                client = TestClient(
                    self.app,
                    base_url="http://testserver",
                    raise_server_exceptions=False,
                    follow_redirects=False,
                    client=(host, 45000),
                )
            except TypeError:  # pragma: no cover - very old TestClient
                client = TestClient(
                    self.app,
                    base_url="http://testserver",
                    raise_server_exceptions=False,
                )
            self._clients[host] = client
        return self._clients[host]

    @staticmethod
    def _headers(api_key: Optional[str], headers: Optional[Dict[str, str]]):
        merged = dict(headers or {})
        if api_key is not None:
            merged["X-API-Key"] = api_key
        return merged

    def create(
        self,
        url: Optional[str] = None,
        *,
        expires_at: Optional[str] = None,
        payload: Optional[Dict[str, Any]] = None,
        api_key: Optional[str] = None,
        host: str = DEFAULT_HOST,
        headers: Optional[Dict[str, str]] = None,
    ):
        if payload is None:
            payload = {}
            if url is not None:
                payload["url"] = url
            if expires_at is not None:
                payload["expires_at"] = expires_at
        return self.client(host).post(
            "/api/links", json=payload, headers=self._headers(api_key, headers)
        )

    def create_ok(self, url: str, **kwargs) -> str:
        response = self.create(url, **kwargs)
        assert response.status_code == 201, "create({0!r}) -> {1}: {2}".format(
            url, response.status_code, response.text[:200]
        )
        return response.json()["code"]

    def visit(
        self,
        code,
        *,
        api_key: Optional[str] = None,
        host: str = DEFAULT_HOST,
        headers: Optional[Dict[str, str]] = None,
    ):
        return self.client(host).get(
            "/" + str(code), headers=self._headers(api_key, headers)
        )

    def stats(
        self,
        code,
        *,
        api_key: Optional[str] = None,
        host: str = DEFAULT_HOST,
        params: Optional[Dict[str, Any]] = None,
    ):
        return self.client(host).get(
            "/api/links/{0}/stats".format(code),
            params=params,
            headers=self._headers(api_key, None),
        )

    # -- database ---------------------------------------------------------
    def _rows(self, sql: str, params=()) -> List[Dict[str, Any]]:
        con = sqlite3.connect(self.db_path)
        con.row_factory = sqlite3.Row
        try:
            return [dict(row) for row in con.execute(sql, params).fetchall()]
        except sqlite3.OperationalError as exc:
            raise AssertionError(
                "sqlite error {0!r} against {1}: does the service honour "
                "LINKS_DB_PATH and create its schema?".format(str(exc), self.db_path)
            )
        finally:
            con.close()

    def link_rows(self) -> List[Dict[str, Any]]:
        return self._rows("SELECT * FROM links ORDER BY id")

    def click_rows(self) -> List[Dict[str, Any]]:
        return self._rows("SELECT * FROM clicks ORDER BY id")

    def link_count(self) -> int:
        return int(self._rows("SELECT COUNT(*) AS n FROM links")[0]["n"])

    def click_count(self) -> int:
        return int(self._rows("SELECT COUNT(*) AS n FROM clicks")[0]["n"])

    def tables(self) -> List[str]:
        return sorted(
            row["name"]
            for row in self._rows("SELECT name FROM sqlite_master WHERE type = 'table'")
        )

    def columns(self, table: str) -> List[str]:
        return [row["name"] for row in self._rows("PRAGMA table_info({0})".format(table))]

    def set_expiry(self, code: str, when: datetime) -> None:
        stamp = when.astimezone(timezone.utc).strftime(TS_FORMAT)
        con = sqlite3.connect(self.db_path)
        try:
            cursor = con.execute(
                "UPDATE links SET expires_at = ? WHERE code = ?", (stamp, code)
            )
            con.commit()
            assert cursor.rowcount == 1, "no links row with code {0!r}".format(code)
        finally:
            con.close()

    def disk_bytes(self) -> bytes:
        blob = b""
        for path in sorted(Path(self.db_path).parent.glob("*")):
            if path.is_file():
                blob += path.read_bytes()
        return blob

    def close(self) -> None:
        for client in self._clients.values():
            try:
                client.close()
            except Exception:  # pragma: no cover - best effort
                pass


@pytest.fixture
def app_factory(tmp_path, monkeypatch, fake_dns):
    counter = itertools.count(1)
    built: List[Harness] = []

    def factory(**env) -> Harness:
        index = next(counter)
        db_path = tmp_path / "app{0}".format(index) / "links.db"
        monkeypatch.setenv("LINKS_DB_PATH", str(db_path))
        for name, value in env.items():
            monkeypatch.setenv(name, str(value))
        harness = Harness(create_app(), db_path)
        built.append(harness)
        return harness

    yield factory

    for harness in built:
        harness.close()


@pytest.fixture
def app(app_factory) -> Harness:
    return app_factory()


# ---------------------------------------------------------------------------
# assertion helpers
# ---------------------------------------------------------------------------
def assert_error(response) -> Dict[str, Any]:
    """Assert the stable error envelope and return the inner error object."""
    assert "application/json" in response.headers.get("content-type", ""), (
        "error responses must be JSON, got "
        + repr(response.headers.get("content-type"))
    )
    body = response.json()
    assert isinstance(body, dict) and "error" in body, (
        "error body must be {'error': {...}}, got " + repr(body)[:200]
    )
    error = body["error"]
    assert isinstance(error, dict), repr(error)[:200]
    assert isinstance(error.get("code"), str) and error["code"], repr(error)[:200]
    assert isinstance(error.get("message"), str) and error["message"], repr(error)[:200]
    return error


def assert_retry_after(response, window: int = 60) -> int:
    value = response.headers.get("retry-after")
    assert value is not None, "a 429 must carry Retry-After"
    assert value.isdigit(), "Retry-After must be whole seconds, got " + repr(value)
    seconds = int(value)
    assert 1 <= seconds <= window, "Retry-After out of range: " + repr(value)
    assert "no-store" in response.headers.get("cache-control", "").lower(), (
        "a 429 must not be cached; Cache-Control was "
        + repr(response.headers.get("cache-control"))
    )
    return seconds


def parse_ts(value: str) -> datetime:
    assert isinstance(value, str), "timestamp must be a string, got " + repr(value)
    text = value.strip()
    if text.endswith(("Z", "z")):
        text = text[:-1] + "+00:00"
    parsed = datetime.fromisoformat(text)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)
"},{"path":"tests/test_round_trip.py","content":""""Round trip: create a link, follow it, pin the redirect contract."""
import re

from conftest import parse_ts

CODE_RE = re.compile(r"^[A-Za-z0-9]{7}$")


def test_creating_a_link_then_following_it_returns_307_to_the_exact_stored_target(app):
    target = "https://example.com/deep/path?a=1&b=two#frag"

    created = app.create(target)
    assert created.status_code == 201, created.text[:300]
    body = created.json()
    assert set(body) >= {"code", "short_url", "url", "created_at", "expires_at"}, body
    code = body["code"]
    assert CODE_RE.match(code), "code must be 7 base62 characters: " + repr(code)
    assert body["url"] == target, "url must be echoed byte for byte"
    assert body["short_url"] == "http://localhost:8000/" + code, body["short_url"]

    followed = app.visit(code)
    assert followed.status_code == 307, (
        "the design pins a 307 redirect, got {0}: {1}".format(
            followed.status_code, followed.text[:200]
        )
    )
    assert followed.headers["location"] == target, (
        "Location must be the stored target verbatim, got "
        + repr(followed.headers.get("location"))
    )
    assert "no-store" in followed.headers.get("cache-control", "").lower(), (
        "a redirect must not be cacheable; Cache-Control was "
        + repr(followed.headers.get("cache-control"))
    )


def test_the_created_row_is_the_single_source_of_the_redirect_target(app):
    target = "http://example.com/only-one"
    code = app.create_ok(target)

    rows = app.link_rows()
    assert len(rows) == 1, rows
    assert rows[0]["code"] == code
    assert rows[0]["url"] == target
    assert parse_ts(rows[0]["expires_at"]) > parse_ts(rows[0]["created_at"])

    assert app.visit(code).headers["location"] == target


def test_short_url_uses_links_base_url_with_any_trailing_slash_stripped(app_factory):
    app = app_factory(LINKS_BASE_URL="https://sho.rt/")

    body = app.create("https://example.com/a").json()

    assert body["short_url"] == "https://sho.rt/" + body["code"], body["short_url"]


def test_two_links_created_in_one_process_get_distinct_codes_and_distinct_targets(app):
    first = app.create_ok("https://example.com/one")
    second = app.create_ok("https://example.com/two")

    assert first != second, "two creations returned the same code"
    assert app.visit(first).headers["location"] == "https://example.com/one"
    assert app.visit(second).headers["location"] == "https://example.com/two"


def test_links_code_length_is_read_from_the_environment(app_factory):
    app = app_factory(LINKS_CODE_LENGTH="10")

    code = app.create_ok("https://example.com/a")

    assert re.match(r"^[A-Za-z0-9]{10}$", code), code
    assert app.visit(code).status_code == 307
"},{"path":"tests/test_open_redirect.py","content":""""Open redirect surface: only http(s) destinations may ever be stored."""
import pytest

from conftest import assert_error

DANGEROUS = [
    "javascript:alert(1)",
    "JavaScript:alert(document.domain)",
    "data:text/html,<script>alert(1)</script>",
    "data:text/html;base64,PHNjcmlwdD5hbGVydCgxKTwvc2NyaXB0Pg==",
    "file:///etc/passwd",
    "FILE://localhost/etc/shadow",
]


@pytest.mark.parametrize("target", DANGEROUS)
def test_a_dangerous_scheme_is_rejected_at_creation_and_writes_no_row(app, target):
    response = app.create(target)

    assert response.status_code == 400, (
        "{0!r} must be refused at creation, got {1}: {2}".format(
            target, response.status_code, response.text[:200]
        )
    )
    error = assert_error(response)
    assert error["code"] == "unsupported_scheme", error
    assert app.link_rows() == [], (
        "a rejected destination left a row behind: " + repr(app.link_rows())
    )
    assert app.link_count() == 0


@pytest.mark.parametrize(
    "target",
    ["//evil.example.com/path", "ftp://files.example.com/secret", "mailto:a@b.test"],
    ids=["protocol_relative", "ftp", "mailto"],
)
def test_a_non_http_target_is_a_4xx_that_stores_nothing(app, target):
    response = app.create(target)

    assert 400 <= response.status_code < 500, (
        "{0!r} produced {1}: {2}".format(target, response.status_code, response.text[:200])
    )
    assert_error(response)
    assert app.link_count() == 0


def test_rejecting_a_dangerous_scheme_leaves_nothing_reachable(app):
    for target in DANGEROUS:
        app.create(target)

    assert app.link_rows() == []
    assert app.click_rows() == []
    # nothing was stored, so no code can resolve to those targets
    assert app.visit("aB3dEf9").status_code == 404


def test_http_and_https_destinations_are_still_accepted_so_this_is_not_deny_everything(app):
    for target in ("http://example.com/plain", "https://example.com/secure"):
        response = app.create(target)
        assert response.status_code == 201, (target, response.text[:200])

    assert app.link_count() == 2
"},{"path":"tests/test_blocked_destinations.py","content":""""SSRF surface: loopback, private and link local targets never get stored."""
import pytest

from conftest import assert_error

BLOCKED = [
    ("cloud_metadata", "http://169.254.169.254/latest/meta-data/"),
    ("link_local", "http://169.254.10.1/x"),
    ("loopback_v4", "http://127.0.0.1:8080/admin"),
    ("loopback_v6", "http://[::1]/x"),
    ("loopback_decimal", "http://2130706433/x"),
    ("private_10", "http://10.0.0.7/x"),
    ("private_172", "http://172.16.5.4/x"),
    ("private_192", "http://192.168.1.1/router"),
    ("unique_local_v6", "http://[fd00::1]/x"),
    ("unspecified", "http://0.0.0.0/x"),
]


@pytest.mark.parametrize("label,target", BLOCKED, ids=[b[0] for b in BLOCKED])
def test_a_private_or_link_local_literal_is_rejected_and_writes_no_row(app, label, target):
    response = app.create(target)

    assert response.status_code == 400, (
        "{0} target {1!r} produced {2}: {3}".format(
            label, target, response.status_code, response.text[:200]
        )
    )
    error = assert_error(response)
    assert error["code"] == "blocked_destination", error
    assert app.link_rows() == [], "a blocked destination left a row behind"


def test_the_cloud_metadata_address_is_blocked_behind_a_hostname_too(app, fake_dns):
    fake_dns.set("metadata.internal.test", ["169.254.169.254"])

    response = app.create("http://metadata.internal.test/latest/meta-data/")

    assert response.status_code == 400, response.text[:200]
    assert assert_error(response)["code"] == "blocked_destination"
    assert app.link_count() == 0
    assert "metadata.internal.test" in fake_dns.lookups, (
        "the host was never resolved, so it cannot have been denylist checked"
    )


def test_a_hostname_resolving_to_loopback_is_rejected_and_writes_no_row(app, fake_dns):
    fake_dns.set("evil.test", ["127.0.0.1"])

    response = app.create("https://evil.test/x")

    assert response.status_code == 400, response.text[:200]
    assert assert_error(response)["code"] == "blocked_destination"
    assert app.link_count() == 0


def test_a_hostname_with_one_private_address_among_public_ones_is_rejected(app, fake_dns):
    fake_dns.set("mixed.test", ["93.184.216.34", "10.0.0.5"])

    response = app.create("https://mixed.test/x")

    assert response.status_code == 400, response.text[:200]
    assert assert_error(response)["code"] == "blocked_destination"
    assert app.link_count() == 0


def test_an_unresolvable_hostname_fails_closed_and_writes_no_row(app, fake_dns):
    fake_dns.fail("nowhere.invalid")

    response = app.create("https://nowhere.invalid/x")

    assert response.status_code == 400, response.text[:200]
    assert assert_error(response)["code"] == "blocked_destination"
    assert app.link_count() == 0


def test_public_addresses_are_still_accepted(app, fake_dns):
    fake_dns.set("good.test", ["93.184.216.34"])

    literal = app.create("http://93.184.216.34/x")
    named = app.create("https://good.test/x")

    assert literal.status_code == 201, literal.text[:200]
    assert named.status_code == 201, named.text[:200]
    assert app.link_count() == 2
"},{"path":"tests/test_expiry.py","content":""""Expiry behaviour. Time is controlled by writing expires_at, never by sleeping."""
from datetime import datetime, timedelta, timezone

import pytest

from conftest import assert_error, parse_ts


def test_an_expired_link_returns_410_with_no_location_header_and_no_click(app):
    code = app.create_ok("https://example.com/gone")
    app.set_expiry(code, datetime.now(timezone.utc) - timedelta(seconds=1))

    response = app.visit(code)

    assert response.status_code == 410, (
        "an expired link must be 410 Gone, got {0}: {1}".format(
            response.status_code, response.text[:200]
        )
    )
    error = assert_error(response)
    assert error["code"] == "link_expired", error
    assert "location" not in {k.lower() for k in response.headers.keys()}, (
        "a 410 must not hand the client a Location"
    )
    assert app.click_rows() == [], "a refused redirect must not be recorded as a click"


def test_an_expired_link_is_distinguishable_from_a_code_that_never_existed(app):
    code = app.create_ok("https://example.com/gone")
    app.set_expiry(code, datetime.now(timezone.utc) - timedelta(days=1))

    expired = app.visit(code)
    unknown = app.visit("Zz9Yy8X")

    assert expired.status_code == 410
    assert unknown.status_code == 404
    assert assert_error(unknown)["code"] == "not_found"


def test_a_link_whose_expiry_is_still_in_the_future_keeps_redirecting(app):
    target = "https://example.com/live"
    code = app.create_ok(target)
    app.set_expiry(code, datetime.now(timezone.utc) + timedelta(days=1))

    response = app.visit(code)

    assert response.status_code == 307, response.text[:200]
    assert response.headers["location"] == target


@pytest.mark.parametrize(
    "value",
    ["2000-01-01T00:00:00Z", "1999-12-31T23:59:59.999999Z"],
    ids=["past_instant", "just_before_2000"],
)
def test_an_expires_at_in_the_past_is_refused_and_writes_no_row(app, value):
    response = app.create("https://example.com/a", expires_at=value)

    assert response.status_code == 400, (value, response.status_code, response.text[:200])
    assert_error(response)
    assert app.link_rows() == []


