    "code",
    ["short", "waytoolongforacode", "abc-def", "abc_def", "1234567890", ".."],
    ids=["too_short", "too_long", "hyphen", "underscore", "ten_digits", "dots"],
)
def test_a_malformed_code_is_a_plain_404_and_not_a_server_error(app, code):
    response = app.visit(code)

    assert response.status_code == 404, (
        "{0!r} should be a plain 404, got {1}: {2}".format(
            code, response.status_code, response.text[:200]
        )
    )
    assert_error(response)
    assert app.link_count() == 0
    assert app.click_count() == 0


def test_stats_for_an_unknown_code_returns_404_with_the_error_envelope(app):
    response = app.stats("Ab3Cd9Z")

    assert response.status_code == 404, response.text[:200]
    assert assert_error(response)["code"] == "not_found"
    assert app.link_count() == 0


def test_a_404_for_one_code_does_not_disturb_an_existing_link(app):
    code = app.create_ok("https://example.com/live")

    assert app.visit("Zz9Yy8X").status_code == 404

    assert app.visit(code).status_code == 307
    assert app.stats(code).json()["total_clicks"] == 1
    assert app.link_count() == 1
"},{"path":"tests/test_click_analytics.py","content":""""Click analytics counts successful redirects and only successful redirects."""
from datetime import datetime, timedelta, timezone

from conftest import TS_FORMAT, parse_ts


def test_a_successful_redirect_increments_the_click_count_exactly_once(app):
    code = app.create_ok("https://example.com/a")
    assert app.stats(code).json()["total_clicks"] == 0

    assert app.visit(code).status_code == 307

    assert app.click_count() == 1, "exactly one click row per successful redirect"
    assert app.stats(code).json()["total_clicks"] == 1


def test_three_redirects_produce_exactly_three_clicks(app):
    code = app.create_ok("https://example.com/a")

    for _ in range(3):
        assert app.visit(code).status_code == 307

    assert app.click_count() == 3
    assert app.stats(code).json()["total_clicks"] == 3


def test_a_404_redirect_does_not_increment_any_click_count(app):
    code = app.create_ok("https://example.com/a")
    assert app.visit(code).status_code == 307

    assert app.visit("Qq1Ww2E").status_code == 404

    assert app.click_count() == 1, "an unknown code was counted as a click"
    assert app.stats(code).json()["total_clicks"] == 1


def test_a_410_redirect_does_not_increment_the_click_count(app):
    code = app.create_ok("https://example.com/a")
    assert app.visit(code).status_code == 307
    app.set_expiry(code, datetime.now(timezone.utc) - timedelta(minutes=5))

    for _ in range(3):
        assert app.visit(code).status_code == 410

    assert app.click_count() == 1, "a refused redirect was counted as a click"
    assert app.stats(code).json()["total_clicks"] == 1


def test_clicks_are_attributed_to_their_own_link_only(app):
    first = app.create_ok("https://example.com/a")
    second = app.create_ok("https://example.com/b")

    app.visit(first)
    app.visit(first)
    app.visit(second)

    assert app.stats(first).json()["total_clicks"] == 2
    assert app.stats(second).json()["total_clicks"] == 1


def test_a_click_records_the_referer_and_user_agent_and_a_utc_timestamp(app):
    code = app.create_ok("https://example.com/a")

    app.visit(
        code,
        headers={"Referer": "https://news.test/story", "User-Agent": "pinning-agent/1.0"},
    )

    entries = app.stats(code).json()["clicks"]
    assert len(entries) == 1, entries
    entry = entries[0]
    assert entry["referrer"] == "https://news.test/story"
    assert entry["user_agent"] == "pinning-agent/1.0"
    datetime.strptime(app.click_rows()[0]["clicked_at"], TS_FORMAT)
    assert parse_ts(entry["timestamp"]) <= datetime.now(timezone.utc) + timedelta(seconds=5)


def test_stats_pages_clicks_newest_first_without_changing_the_total(app):
    code = app.create_ok("https://example.com/a")
    for i in (1, 2, 3):
        app.visit(code, headers={"Referer": "https://ref{0}.test/".format(i)})

    body = app.stats(code).json()
    assert body["total_clicks"] == 3
    assert [c["referrer"] for c in body["clicks"]] == [
        "https://ref3.test/",
        "https://ref2.test/",
        "https://ref1.test/",
    ]

    page_one = app.stats(code, params={"limit": 2, "offset": 0}).json()
    page_two = app.stats(code, params={"limit": 2, "offset": 2}).json()
    assert page_one["total_clicks"] == 3 and page_two["total_clicks"] == 3
    assert len(page_one["clicks"]) == 2 and len(page_two["clicks"]) == 1


def test_the_clicks_table_has_no_column_capable_of_holding_a_client_address(app):
    code = app.create_ok("https://example.com/a")
    app.visit(code)

    for column in app.columns("clicks"):
        low = column.lower()
        assert "ip" not in low, column
        assert "addr" not in low, column
        assert "remote" not in low, column
        assert "client" not in low, column
"}],"coverage_notes":"tests/test_round_trip.py pins the create->follow round trip (201 body shape, 7-char base62 code, short_url built from LINKS_BASE_URL with the trailing slash stripped, 307 + exact Location + Cache-Control: no-store) and LINKS_CODE_LENGTH. tests/test_open_redirect.py covers javascript:, data: and file: (plus case variants and protocol-relative/ftp/mailto) rejected with 400 unsupported_scheme and asserts the links table is empty afterwards, with a positive control that http/https still succeed. tests/test_blocked_destinations.py covers 169.254.169.254, other link-local, loopback (v4, v6, and the 2130706433 decimal literal), 10/172.16/192.168, fd00::/7 and 0.0.0.0, plus hostnames resolving to metadata/loopback/mixed sets and an unresolvable host failing closed - each asserting 400 blocked_destination and zero rows. tests/test_expiry.py uses a direct DB write of a past expires_at (never sleeps) for 410 link_expired with no Location and no click row, distinguishes 410 from 404, rejects past/unparseable expires_at with no row, and checks the configured default TTL. tests/test_rate_limit.py drives the per-IP creation bucket past LINKS_RATE_LIMIT_MAX (429 rate_limited, Retry-After whole seconds 1..60, Cache-Control no-store, no row written), shows a different client key still gets 201, honours LINKS_RATE_LIMIT_MAX/LINKS_RATE_LIMIT_ENABLED, and reopens the window by advancing an injected fake clock (patched onto app.ratelimit's time reference). tests/test_api_key_rate_limit.py covers every SHORTENER_API_KEYS acceptance criterion: alpha 100/101st 429 with no row, independent alpha/beta buckets, no double-charging of the per-IP bucket at MAX=2, unknown key falling back with no 401/403, anonymous legacy behaviour, Retry-After format, window rollover via the fake clock, redirects still served at MAX*100 after the creation quota is spent, stats never limited, unset keys unchanged, the malformed 'alpha,beta:abc,gamma:0,:5,delta:20' list, whitespace trimming, case sensitivity, disabled limiter, schema/table/disk-bytes containment, and no key echo in body/headers/DEBUG logs. tests/test_code_collision.py forces the generator to return an existing code (patching app.main.generate_code and app.codes.generate_code) and pins retry-to-uniqueness plus a bounded LINKS_CODE_MAX_ATTEMPTS=3 giving 503 code_generation_failed with exactly three attempts (no hang, no 500). tests/test_unknown_code.py pins 404 not_found for unknown/malformed codes and stats, creating nothing. tests/test_click_analytics.py pins one increment per successful redirect, no increment on 404 or 410, per-link attribution, referrer/user-agent capture, paging, and the absence of any IP-shaped column.

DESIGN vs IMPLEMENTATION mismatches (findings; tests follow the implementation as instructed): (1) The shipped code contains no SHORTENER_API_KEYS support at all - app/config.Settings has no api_key_quotas and app/ratelimit only keys on the client address - so every test in tests/test_api_key_rate_limit.py will fail until the feature lands. (2) TTL configuration differs: design says LINKS_DEFAULT_TTL_SECONDS/LINKS_MAX_TTL_SECONDS with a ttl_seconds request field and NULL = never expires; the code uses LINKS_DEFAULT_TTL_DAYS (default 30) and an ISO-8601 expires_at body field with a NOT NULL expires_at column. Tests use the implementation's names. (3) links schema differs: design specifies target_url/click_count/last_clicked_at; the code stores url and derives totals from the clicks table, so the column assertions pin id,code,url,created_at,expires_at and id,link_id,clicked_at,referrer,user_agent. (4) LINKS_DB_PATH default is ./links.db in code vs ./data/links.db in the design; tests always set it explicitly. (5) LINKS_MAX_TRACKED_KEYS is not read by the code (a hard-coded MAX_TRACKED_KEYS = 20000 is used) and the code adds LINKS_TRUST_FORWARDED_FOR, LINKS_DNS_RESOLUTION_ENABLED, LINKS_STATS_* which the design omits; the limiter clock is not injectable, so the window tests patch app.ratelimit.time and will need updating if an injected clock replaces it. (6) The design's clock injection and LRU bucket-map separation, the 2048-char URL limit boundary, and health/stats validation edge cases are deliberately not covered here beyond what the listed criteria require; no test asserts log output."}

